, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "516ec5a6-e52e-5335-899b-cd72ca1c0685"}, {"title": "琉球等地遣使来贡", "description": "本纪记载，琉球、暹罗、安南和占城在这一年入贡。 按原历纪年，事情发生在公元1384至1385年之间。", "start_year": null, "end_year": null, "time_original": "洪武十七年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4638aafd-5f4a-588f-9085-313f39b2dcc0"}, {"title": "明廷在南郊祭祀天地", "description": "明廷在南郊举行祭祀天地的大礼。", "start_year": 1385, "end_year": 1385, "time_original": "洪武十八年正月辛未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "97264be5-1e44-5abf-b23b-b89455007fcf"}, {"title": "明廷按五等考核入朝官员", "description": "朝廷把入朝官员的考核结果划为五个等级，按等次予以升降。", "start_year": 1385, "end_year": 1385, "time_original": "洪武十八年正月癸酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3074c4d5-d726-5588-8133-3c5d118fead2"}, {"title": "朱元璋因久雨雷雹诏求直言", "description": "连日阴雨并出现雷雹，朱元璋下诏让臣民直陈时政的得失。", "start_year": 1385, "end_year": 1385, "time_original": "洪武十八年二月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7b0544bb-a1c1-5bc8-af98-7c3f28861bae"}, {"title": "魏国公徐达去世", "description": "本纪记载，魏国公徐达在二月己未去世。", "start_year": 1385, "end_year": 1385, "time_original": "洪武十八年二月己未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "dab793f2-699a-5d9c-8d9a-3ffb50793089"}, {"title": "明廷赐丁显等进士及第或出身", "description": "朝廷分别赐丁显等人进士及第或出身。", "start_year": 1385, "end_year": 1385, "time_original": "洪武十八年三月壬戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "11a6ab2e-ea07-57ec-b1bf-907860aa9e06"}, {"title": "明廷定下官府协助送还任所亲丧的规例", "description": "在京和地方官员的父母若在任所去世，由主管官署提供舟车，将灵柩送回家乡。朝廷将此定为规例。", "start_year": 1385, "end_year": 1385, "time_original": "洪武十八年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9ba6cd35-7f5a-5cbb-8bed-618edd78f3ed"}, {"title": "明廷免征畿内本年田租", "description": "朝廷下令免去畿内当年的田租。", "start_year": 1385, "end_year": 1385, "time_original": "洪武十八年三月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7a31d02a-5571-53f9-be2a-fd5ecae37533"}, {"title": "明廷命各地掩埋暴露遗骨", "description": "朝廷命各地郡县掩埋暴露在外的遗骨。", "start_year": 1385, "end_year": 1385, "time_original": "洪武十八年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ce3bb5b3-de43-5375-bbdb-cba42f0833e1"}, {"title": "明廷开始从进士中选任庶吉士", "description": "朝廷首次选派进士到翰林院、承敕监和六科担任庶吉士。", "start_year": 1385, "end_year": 1385, "time_original": "洪武十八年三月丙子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "86402aef-4a65-5efb-b3b1-bed29b1410a8"}, {"title": "户部侍郎郭桓被处死", "description": "本纪记载，户部侍郎郭桓因被指盗取官粮而被处死。", "start_year": 1385, "end_year": 1385, "time_original": "洪武十八年三月己丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3e0221a5-14af-5556-aec7-4a12772dc824"}, {"title": "吏部尚书余熂获罪被处死", "description": "吏部尚书余熂获罪被处死，本纪此处未列罪名。", "start_year": 1385, "end_year": 1385, "time_original": "洪武十八年四月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c9015d4d-1147-54b5-82c8-d7fe54f22982"}, {"title": "汤和周德兴随楚王朱桢出兵思州", "description": "思州发生反抗。朝廷任命汤和为征虏将军、周德兴为副将军，二人率军随楚王朱桢出讨。", "start_year": 1385, "end_year": 1385, "time_original": "洪武十八年四月丙辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d4113305-ebd4-5597-8a8e-a0f217713a78"}, {"title": "明廷规定地方官每三年入朝一次", "description": "朝廷规定地方官每三年入朝一次，并将这一规定定为成令。", "start_year": 1385, "end_year": 1385, "time_original": "洪武十八年六月戊申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "08ee10b5-fa8e-51b3-a077-17f3fdcf6d63"}, {"title": "明廷册封王禑为高丽国王", "description": "朝廷册封王禑为高丽国王。", "start_year": 1385, "end_year": 1385, "time_original": "洪武十八年七月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0240d4db-dda1-5451-b403-91f9543c9649"}, {"title": "五开发生反抗", "description": "本纪记载，五开于七月庚辰发生反抗。", "start_year": 1385, "end_year": 1385, "time_original": "洪武十八年七月庚辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a1b7ec7b-98de-5537-abaf-a1c13e4ee7a5"}, {"title": "冯胜傅友德蓝玉在北平备边", "description": "冯胜、傅友德、蓝玉在北平部署边防。", "start_year": 1385, "end_year": 1385, "time_original": "洪武十八年八月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3ee66df6-a583-5ce7-a676-2b07a44d0e82"}, {"title": "明廷赈济河南水灾", "description": "朝廷在这个月赈济河南水灾。", "start_year": 1385, "end_year": 1385, "time_original": "洪武十八年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "28902e86-587f-5683-8b04-571df88144c0"}, {"title": "明廷向各地颁布《大诰》", "description": "朝廷向天下颁布《大诰》。", "start_year": 1385, "end_year": 1385, "time_original": "洪武十八年十月己丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5d73073c-785e-546b-b04e-849a32b7db1a"}, {"title": "明廷召回冯胜", "description": "朝廷下令召回冯胜。", "start_year": 1385, "end_year": 1385, "time_original": "洪武十八年十月癸卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8d40ca8f-3196-5f9e-846a-6daf8bd4a287"}, {"title": "明廷下诏免去圣贤后裔的输作", "description": "朱元璋以孟子的后人因罪服劳役为由，下诏访查各地，免去因罪服役的圣贤后人的输作。", "start_year": 1385, "end_year": 1385, "time_original": "洪武十八年十月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7bc1c626-b1d4-5e01-86ce-605e68edc3a8"}, {"title": "楚王朱桢和汤和平定五开战事", "description": "本纪记载，楚王朱桢和信国公汤和在这个月平定五开战事。", "start_year": 1385, "end_year": 1385, "time_original": "洪武十八年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "122b722b-685d-5996-8653-dd2b0dc3051c"}, {"title": "明廷免征河南山东北平田租", "description": "朝廷免去河南、山东和北平的田租。", "start_year": 1385, "end_year": 1385, "time_original": "洪武十八年十一月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c3432cc5-9dc4-514c-adf9-6d93647f8ff9"}, {"title": "明廷命有关官署荐举孝廉", "description": "朝廷下诏命主管官署荐举孝廉。", "start_year": 1386, "end_year": 1386, "time_original": "洪武十八年十二月丙午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "360a48d1-22c6-526c-91c3-716c7c489c59"}, {"title": "思伦发起兵，冯诚战败", "description": "本纪记载，麓川平缅宣慰使思伦发起兵反明，都督冯诚交战失利，千户王昇战死。", "start_year": 1386, "end_year": 1386, "time_original": "洪武十八年十二月癸丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7048a68b-8da8-569f-bd73-f0fb37868c46"}, {"title": "高丽等地遣使来贡", "description": "本纪记载，高丽、琉球、安南和暹罗在这一年入贡。 按原历纪年，事情发生在公元1385至1386年之间。", "start_year": null, "end_year": null, "time_original": "洪武十八年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7e8aae55-6d26-573d-a93f-bfaf0d915c16"}]'::jsonb)
